To solve this problem, we need to format a logging event into a string based on a specified conversion pattern. The conversion pattern contains placeholders (e.g., %d for date, %m for message) that should be replaced with corresponding values from the logging event.

### Approach
1. **Parsing the Conversion Pattern**: The conversion pattern is parsed to identify literal text and conversion specifiers. Conversion specifiers start with a '%' followed by a key (e.g., 'd' for date) and optional options enclosed in braces (e.g., %d{yyyy-MM-dd}).
2. **Handling Escaped Percent Signs**: '%%' in the pattern is treated as a literal '%'.
3. **Resolving Conversion Specifiers**: Each conversion specifier is mapped to a corresponding value from the logging event. For example, '%d' is replaced with the formatted timestamp, and '%m' is replaced with the event message.
4. **Formatting Values**: Values are formatted according to their specifiers. For example, dates are formatted using a specified or default date format.

### Solution Code
```java
import java.text.SimpleDateFormat;
import java.util.Date;

public class LogFormatter {
    private String conversionPattern;

    public LogFormatter(String conversionPattern) {
        this.conversionPattern = conversionPattern;
    }

    public String format(LoggingEvent event) {
        StringBuilder sb = new StringBuilder();
        int pos = 0;
        while (pos < conversionPattern.length()) {
            char c = conversionPattern.charAt(pos);
            if (c == '%') {
                pos++;
                if (pos >= conversionPattern.length()) {
                    sb.append('%');
                    break;
                }
                char nextChar = conversionPattern.charAt(pos);
                if (nextChar == '%') {
                    sb.append('%');
                    pos++;
                } else {
                    StringBuilder keyBuilder = new StringBuilder();
                    while (pos < conversionPattern.length() && Character.isLetter(conversionPattern.charAt(pos))) {
                        keyBuilder.append(conversionPattern.charAt(pos));
                        pos++;
                    }
                    String key = keyBuilder.toString();
                    String options = null;
                    if (pos < conversionPattern.length() && conversionPattern.charAt(pos) == '{') {
                        pos++;
                        int braceStart = pos;
                        while (pos < conversionPattern.length() && conversionPattern.charAt(pos) != '}') {
                            pos++;
                        }
                        if (pos < conversionPattern.length()) {
                            options = conversionPattern.substring(braceStart, pos);
                            pos++;
                        } else {
                            options = conversionPattern.substring(braceStart);
                        }
                    }
                    String value = resolveConversion(key, options, event);
                    sb.append(value);
                }
            } else {
                sb.append(c);
                pos++;
            }
        }
        return sb.toString();
    }

    private String resolveConversion(String key, String options, LoggingEvent event) {
        switch (key) {
            case "d":
                long timestamp = event.getTimeStamp();
                String datePattern = (options != null) ? options : "yyyy-MM-dd HH:mm:ss,SSS";
                try {
                    SimpleDateFormat sdf = new SimpleDateFormat(datePattern);
                    return sdf.format(new Date(timestamp));
                } catch (IllegalArgumentException e) {
                    SimpleDateFormat defaultSdf = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss,SSS");
                    return defaultSdf.format(new Date(timestamp));
                }
            case "p":
            case "level":
                return event.getLevel().toString();
            case "m":
            case "message":
                return event.getMessage().toString();
            case "c":
            case "logger":
                return event.getLoggerName();
            case "t":
            case "thread":
                return event.getThreadName();
            case "n":
                return System.lineSeparator();
            default:
                return "%" + key;
        }
    }
}

