                throw new RuntimeException("Dist path is not a directory: " + distPath);
            }
            if (!distDir.canWrite()) {
                throw new RuntimeException("Dist directory is not writable: " + distPath);
            }
        }
    }

    // Assume distPath has a setter method if needed
