import com.google.gson.JsonObject;
import com.google.gson.JsonElement;
import com.google.gson.JsonPrimitive;
import com.google.gson.JsonArray;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class ContentBuilder {

    private Map<String, Object> buildContent(JsonObject jsonObject) {
        Map<String, Object> contentMap = new HashMap<>();
        boolean hasAts = jsonObject.has("ats");

        Map<String, Object> atsMap = new HashMap<>();

        for (Map.Entry<String, JsonElement> entry : jsonObject.entrySet()) {
            String key = entry.getKey();
            JsonElement valueElement = entry.getValue();
            Object value = convertJsonElement(valueElement);

            if (!hasAts && key.startsWith("@")) {
                String atKey = key.substring(1);
                atsMap.put(atKey, value);
            } else {
                contentMap.put(key, value);
            }
        }

        if (!hasAts && !atsMap.isEmpty()) {
            contentMap.put("ats", atsMap);
        }

        return contentMap;
    }

    private Object convertJsonElement(JsonElement element) {
        if (element == null || element.isJsonNull()) {
            return null;
        } else if (element.isJsonPrimitive()) {
            JsonPrimitive primitive = element.getAsJsonPrimitive();
            if (primitive.isBoolean()) {
                return primitive.getAsBoolean();
            } else if (primitive.isNumber()) {
                return primitive.getAsNumber();
            } else {
                return primitive.getAsString();
            }
        } else if (element.isJsonArray()) {
            JsonArray array = element.getAsJsonArray();
            List<Object> list = new ArrayList<>();
            for (JsonElement e : array) {
                list.add(convertJsonElement(e));
            }
            return list;
        } else if (element.isJsonObject()) {
            JsonObject obj = element.getAsJsonObject();
            return buildContent(obj);
        } else {
            return null;
        }
    }
}
```

### Explanation
- **Check for Existing 'ats' Key**: The presence of an 'ats' key in the input JSON determines whether '@' prefixed keys are processed into a separate map or treated as regular entries.
